-- ----------------------------
-- Table structure for rag_eval_run
-- ----------------------------
DROP TABLE IF EXISTS `rag_eval_run`;
CREATE TABLE `rag_eval_run`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `pipeline` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'baseline/reranker/rewriting/rewriting+reranker',
  `total_count` int NOT NULL COMMENT '本次跑了多少条',
  `hit_at_3` decimal(6, 4) NULL DEFAULT NULL COMMENT 'Hit@3 命中率',
  `mrr_at_5` decimal(6, 4) NULL DEFAULT NULL COMMENT 'MRR@5',
  `ndcg_at_5` decimal(6, 4) NULL DEFAULT NULL COMMENT 'NDCG@5 指标',
  `avg_latency_ms` int NULL DEFAULT NULL COMMENT '平均检索耗时(ms)',
  `detail_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '每条 query 的命中详情 JSON',
  `config_snapshot` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '本次运行的关键参数快照',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pipeline_time`(`pipeline` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RAG 评估运行结果' ROW_FORMAT = DYNAMIC;

